  "auth.consent.merchantApp": "ਹਾਂ, {shop} {brand} ਰਾਹੀਂ ਮੈਨੂੰ ਟੈਕਸਟ, ਈਮੇਲ ਅਤੇ ਪੁਸ਼ ਰਾਹੀਂ ਆਫ਼ਰ ਅਤੇ ਖ਼ਬਰਾਂ ਭੇਜ ਸਕਦੇ ਹਨ। STOP ਲਿਖ ਕੇ ਜਵਾਬ ਦੇਣ ਜਾਂ ਅਨਸਬਸਕ੍ਰਾਈਬ 'ਤੇ ਟੈਪ ਕਰਨ ਨਾਲ ਮੈਂ ਕਦੇ ਵੀ ਅਨਸਬਸਕ੍ਰਾਈਬ ਕਰ ਸਕਦਾ/ਸਕਦੀ ਹਾਂ।",
  "auth.consent.global": "ਮੈਂ ਜਿਨ੍ਹਾਂ ਦੁਕਾਨਾਂ ਨਾਲ ਜੁੜਦਾ/ਜੁੜਦੀ ਹਾਂ, ਉਨ੍ਹਾਂ ਦੇ ਆਫ਼ਰ ਅਤੇ ਖ਼ਬਰਾਂ ਮੈਨੂੰ ਟੈਕਸਟ ਅਤੇ ਈਮੇਲ ਰਾਹੀਂ ਭੇਜੋ। ਮੈਂ ਕਦੇ ਵੀ ਅਨਸਬਸਕ੍ਰਾਈਬ ਕਰ ਸਕਦਾ/ਸਕਦੀ ਹਾਂ।",
  "auth.consent.globalCaption": "ਹਰ ਸੁਨੇਹੇ ਵਿੱਚ ਦੁਕਾਨ ਦਾ ਨਾਂ ਹੁੰਦਾ ਹੈ। ਤੁਸੀਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਕਿਸੇ ਵੀ ਦੁਕਾਨ ਲਈ ਇਸਨੂੰ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ।",
