  "sh.pass.how": "ਕਿਸੇ ਵੀ {brand} ਦੁਕਾਨ ਦੇ ਕਾਊਂਟਰ ਤੇ ਇਹ ਕਾਰਡ ਦਿਖਾਓ। ਸਟਾਫ਼ ਕੋਡ ਸਕੈਨ ਕਰਕੇ ਪੁਆਇੰਟ ਜੋੜਦਾ ਹੈ ਜਾਂ ਇਨਾਮ ਰਿਡੀਮ ਕਰਦਾ ਹੈ। ਤੁਹਾਡੀ ਗਲੀ ਦੀ ਹਰ ਦੁਕਾਨ ਲਈ ਇੱਕ ਕਾਰਡ।",
  "sh.fs.meta.title": "ਖ਼ਰੀਦਦਾਰਾਂ ਲਈ",
  "sh.fs.meta.desc": "ਤੁਹਾਡੀ ਗਲੀ ਦੀ ਹਰ ਦੁਕਾਨ ਲਈ ਇੱਕ ਕਾਰਡ। ਆਪਣੀਆਂ ਪਸੰਦੀਦਾ ਲੋਕਲ ਥਾਵਾਂ ਤੇ ਇਨਾਮ ਕਮਾਓ। ਮੁਫ਼ਤ, ਅਤੇ ਤੁਹਾਡੇ ਪੁਆਇੰਟ ਕਦੇ ਖ਼ਤਮ ਨਹੀਂ ਹੁੰਦੇ।",
  "sh.fs.h1": "ਤੁਹਾਡੀ ਗਲੀ ਦੀ ਹਰ ਦੁਕਾਨ ਲਈ ਇੱਕ ਕਾਰਡ।",
  "sh.fs.lead": "ਆਪਣੀਆਂ ਪਸੰਦੀਦਾ ਲੋਕਲ ਥਾਵਾਂ ਤੇ ਇਨਾਮ ਕਮਾਓ। ਮੁਫ਼ਤ, ਕਿਸੇ ਐਪ ਦੀ ਲੋੜ ਨਹੀਂ, ਅਤੇ ਤੁਹਾਡੇ ਪੁਆਇੰਟ ਕਦੇ ਖ਼ਤਮ ਨਹੀਂ ਹੁੰਦੇ।",
  "sh.fs.ctaFind": "ਮੇਰੇ ਨੇੜਲੀਆਂ ਦੁਕਾਨਾਂ ਲੱਭੋ",
