  "sh.fs.scanOr": "ਜਾਂ ਕਿਸੇ ਵੀ ਸ਼ਾਮਲ ਦੁਕਾਨ ਤੇ QR ਸਕੈਨ ਕਰੋ। ਐਪ ਪਸੰਦ ਹੈ?",
  "sh.fs.stepsTitle": "ਤਿੰਨ ਕਦਮ, ਕਿਸੇ ਐਪ ਦੀ ਲੋੜ ਨਹੀਂ।",
  "sh.fs.how": "ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
  "sh.fs.s1t": "ਸਕੈਨ ਕਰੋ ਜਾਂ ਆਪਣਾ ਨੰਬਰ ਦਿਓ",
  "sh.fs.s1b": "ਕਾਊਂਟਰ ਤੇ QR ਸਕੈਨ ਕਰੋ, ਜਾਂ ਸਟਾਫ਼ ਨੂੰ ਆਪਣਾ ਨੰਬਰ ਦੱਸੋ। 30 ਸਕਿੰਟ ਅਤੇ ਇੱਕ ਟੈਕਸਟ ਕੋਡ।",
  "sh.fs.s2t": "ਇਸਨੂੰ ਆਪਣੇ ਫ਼ੋਨ ਵਿੱਚ ਰੱਖੋ (ਵਿਕਲਪਿਕ)",
  "sh.fs.s2b": "ਕਾਰਡ ਨੂੰ Apple ਜਾਂ Google Wallet ਵਿੱਚ ਜੋੜੋ। ਇਹ ਤੁਹਾਡੀ ਲੌਕ ਸਕ੍ਰੀਨ ਤੇ ਰਹਿੰਦਾ ਹੈ ਅਤੇ ਆਪਣੇ ਆਪ ਅੱਪਡੇਟ ਹੁੰਦਾ ਹੈ। ਨਾ ਐਪ, ਨਾ ਪਾਸਵਰਡ।",
  "sh.fs.s3t": "ਪੂਰੀ ਗਲੀ ਵਿੱਚ ਕਮਾਓ",
  "sh.fs.s3b": "ਹਰ ਦੁਕਾਨ ਤੇ ਪੁਆਇੰਟ ਜਾਂ ਸਟੈਂਪ, ਸਭ ਇੱਕ ਕਾਰਡ ਤੇ। ਸਟ੍ਰੀਟ ਪਾਸਪੋਰਟ ਨਾਲ ਦੀ ਦੁਕਾਨ ਅਜ਼ਮਾਉਣ ਤੇ ਇਨਾਮ ਦਿੰਦੇ ਹਨ।",
  "sh.fs.liveNow": "ਹੁਣ ਚਾਲੂ",
  "sh.fs.whereTitle": "ਤੁਹਾਡਾ ਕਾਰਡ ਕਿੱਥੇ ਚੱਲਦਾ ਹੈ।",
  "sh.fs.shopsN": "{n, plural, one {# ਦੁਕਾਨ} other {# ਦੁਕਾਨਾਂ}}",
  "sh.fs.passportOn": "ਹੁਣ ਚਾਲੂ: {name}",
  "sh.fs.passportLine": "{goal} ਦੁਕਾਨਾਂ ਤੇ ਜਾਓ ਅਤੇ ਡ੍ਰਾਅ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ। {date} ਨੂੰ ਖ਼ਤਮ।",
  "sh.fs.dataEyebrow": "ਤੁਹਾਡਾ ਡੇਟਾ",
  "sh.fs.dataTitle": "ਮੂਲ ਰੂਪ ਵਿੱਚ ਨਿੱਜੀ।",
  "sh.fs.d1t": "ਦੁਕਾਨਾਂ ਸਿਰਫ਼ ਆਪਣੇ ਗਾਹਕ ਦੇਖਦੀਆਂ ਹਨ",
  "sh.fs.d1b": "ਕੈਫ਼ੇ ਇਹ ਨਹੀਂ ਦੇਖਦਾ ਕਿ ਤੁਸੀਂ ਕਿਤਾਬਾਂ ਦੀ ਦੁਕਾਨ ਤੋਂ ਕੀ ਖ਼ਰੀਦਿਆ।",
  "sh.fs.d2t": "ਅਸੀਂ ਤੁਹਾਡਾ ਡੇਟਾ ਕਦੇ ਨਹੀਂ ਵੇਚਦੇ",
  "sh.fs.d2b": "ਆਪਣੇ ਕਾਰਡ ਤੋਂ ਕਦੇ ਵੀ ਸਭ ਕੁਝ ਡਾਊਨਲੋਡ ਕਰੋ ਜਾਂ ਮਿਟਾ ਦਿਓ।",
  "sh.fs.d3t": "ਆਫ਼ਰ ਸਿਰਫ਼ ਤਦ ਜਦ ਤੁਸੀਂ ਹਾਂ ਕਹੋ",
  "sh.fs.d3b": "ਹਰ ਦੁਕਾਨ ਵੱਖਰੇ ਤੌਰ ਤੇ ਪੁੱਛਦੀ ਹੈ। ਰੋਕਣ ਲਈ ਕਿਸੇ ਵੀ ਟੈਕਸਟ ਦਾ ਜਵਾਬ STOP ਲਿਖ ਕੇ ਦਿਓ।",
  "sh.fs.faqTitle": "ਸਵਾਲ।",
  "sh.fs.q1": "ਕੀ ਇਸਦੀ ਕੋਈ ਕੀਮਤ ਹੈ?",
  "sh.fs.a1": "ਨਹੀਂ। ਤੁਹਾਡੇ ਲਈ ਇਹ ਹਮੇਸ਼ਾ ਮੁਫ਼ਤ ਹੈ।",
  "sh.fs.q2": "ਕੀ ਮੈਨੂੰ ਐਪ ਚਾਹੀਦੀ ਹੈ?",
  "sh.fs.a2": "ਨਹੀਂ। ਕਾਊਂਟਰ ਤੇ QR ਸਕੈਨ ਕਰੋ ਅਤੇ ਤੁਸੀਂ ਜੁੜ ਗਏ। ਤੁਸੀਂ ਆਪਣਾ ਕਾਰਡ Apple Wallet ਜਾਂ Google Wallet ਵਿੱਚ ਜੋੜ ਸਕਦੇ ਹੋ, ਜਾਂ ਬਾਅਦ ਵਿੱਚ {brand} ਐਪ ਲੈ ਸਕਦੇ ਹੋ।",
  "sh.fs.q3": "ਕੀ ਮੇਰੇ ਪੁਆਇੰਟ ਖ਼ਤਮ ਹੋ ਜਾਂਦੇ ਹਨ?",
  "sh.fs.a3": "ਨਹੀਂ, ਜਦ ਤੱਕ ਕੋਈ ਦੁਕਾਨ ਮਿਆਦ ਚਾਲੂ ਨਾ ਕਰੇ। ਜੇ ਕਰਦੀ ਹੈ ਤਾਂ ਨਿਯਮ ਤੁਹਾਡੇ ਬੈਲੇਂਸ ਕੋਲ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।",
  "sh.fs.q4": "ਕੀ ਇੱਕ ਦੁਕਾਨ ਦੇ ਪੁਆਇੰਟ ਦੂਜੀ ਦੁਕਾਨ ਤੇ ਚੱਲ ਸਕਦੇ ਹਨ?",
  "sh.fs.a4": "ਪੁਆਇੰਟ ਉਸੇ ਦੁਕਾਨ ਤੇ ਰਹਿੰਦੇ ਹਨ ਜਿੱਥੇ ਤੁਸੀਂ ਕਮਾਏ। ਮੁਹੱਲੇ ਦੇ ਬੋਨਸ ਗਲੀ ਦੀਆਂ ਹੋਰ ਦੁਕਾਨਾਂ ਤੇ ਜਾਣ ਦਾ ਇਨਾਮ ਦਿੰਦੇ ਹਨ।",
  "sh.fs.q5": "ਕੀ ਮੈਂ ਇਸਨੂੰ ਹਿੰਦੀ, ਉਰਦੂ ਜਾਂ ਪੰਜਾਬੀ ਵਿੱਚ ਵਰਤ ਸਕਦਾ/ਸਕਦੀ ਹਾਂ?",
  "sh.fs.a5": "ਹਾਂ। ਪੰਨੇ ਦੇ ਉੱਪਰ ਜਾਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਆਪਣੀ ਭਾਸ਼ਾ ਚੁਣੋ। ਤੁਹਾਡੇ ਟੈਕਸਟ, ਅਲਰਟ ਅਤੇ ਵਾਲਿਟ ਪਾਸ ਉਸੇ ਭਾਸ਼ਾ ਵਿੱਚ ਆਉਂਦੇ ਹਨ।",
  "sh.fs.q6": "ਟੈਕਸਟ ਕਿਵੇਂ ਬੰਦ ਕਰਾਂ?",
  "sh.fs.a6": "ਕਿਸੇ ਵੀ ਸੁਨੇਹੇ ਦਾ ਜਵਾਬ STOP ਲਿਖ ਕੇ ਦਿਓ, ਜਾਂ ਆਪਣੇ ਕਾਰਡ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਹਰ ਦੁਕਾਨ ਲਈ ਬਦਲੋ।",
