  "cp.consent.sender": "ਮੈਸੇਜ {shop} ਵੱਲੋਂ ਆਉਂਦੇ ਹਨ, {brand} ਰਾਹੀਂ ਭੇਜੇ ਜਾਂਦੇ ਹਨ।",
  "cp.consent.pushTitle": "ਇਨਾਮ ਮਿਲਦੇ ਹੀ ਜਾਣੋ",
  "cp.consent.pushBody": "ਅਸੀਂ ਤੁਹਾਨੂੰ ਸਿਰਫ਼ ਤੁਹਾਡੇ ਪੁਆਇੰਟ, ਇਨਾਮ ਅਤੇ ਆਰਡਰ ਬਾਰੇ ਦੱਸਾਂਗੇ। ਆਫ਼ਰ ਉਦੋਂ ਤੱਕ ਬੰਦ ਹਨ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਨੂੰ ਚਾਲੂ ਨਾ ਕਰੋ।",
  "cp.consent.withdrawn": "ਹੋ ਗਿਆ। {shop} ਹੁਣ ਤੁਹਾਨੂੰ ਆਫ਼ਰ ਨਹੀਂ ਭੇਜੇਗਾ। ਤੁਹਾਡੇ {terminology} ਪਹਿਲਾਂ ਵਾਂਗ ਕੰਮ ਕਰਦੇ ਰਹਿਣਗੇ।",
  "cp.empty.activityBody": "ਤੁਹਾਡੀ ਪਹਿਲੀ ਵਿਜ਼ਿਟ ਤੋਂ ਬਾਅਦ ਤੁਹਾਡੇ {terminology} ਅਤੇ ਇਨਾਮ ਇੱਥੇ ਦਿਸਣਗੇ।",
  "cp.empty.campaignsTitle": "ਨੇੜੇ ਕੋਈ ਪਾਸਪੋਰਟ ਨਹੀਂ ਚੱਲ ਰਿਹਾ",
  "cp.empty.campaignsBody": "ਜਦੋਂ ਤੁਹਾਡੇ ਮੁਹੱਲੇ ਵਿੱਚ ਪਾਸਪੋਰਟ ਜਾਂ ਪੁਆਇੰਟ ਵੀਕੈਂਡ ਚੱਲੇਗਾ, ਤਾਂ ਤੁਹਾਡੀ ਤਰੱਕੀ ਇੱਥੇ ਦਿਸੇਗੀ।",
  "cp.empty.mapSearchTitle": "\"{query}\" ਨਾਲ ਮਿਲਦੀ ਕੋਈ ਦੁਕਾਨ ਨਹੀਂ",
  "cp.empty.mapSearchBody": "ਕੋਈ ਹੋਰ ਸ਼ਬਦ ਅਜ਼ਮਾਓ, ਜਾਂ ਨਕਸ਼ਾ ਜ਼ੂਮ ਆਊਟ ਕਰੋ।",
  "cp.empty.noHoodTitle": "ਅਸੀਂ ਹਾਲੇ ਤੁਹਾਡੀ ਗਲੀ ਵਿੱਚ ਨਹੀਂ ਹਾਂ",
  "cp.empty.noHoodBody": "ਅਸੀਂ ਇੱਕ-ਇੱਕ ਮੁਹੱਲੇ ਵਿੱਚ ਸ਼ੁਰੂ ਕਰਦੇ ਹਾਂ। ਕੀ ਤੁਸੀਂ ਚਾਹੁੰਦੇ ਹੋ ਕਿ ਅਸੀਂ ਤੁਹਾਡੇ ਮੁਹੱਲੇ ਵਿੱਚ ਆਈਏ?",
